package mx.elmuelle.pdv;
import org.junit.Test;import static org.junit.Assert.*;import java.net.*;import java.io.*;
public class LanPrinterTransportTest {
 @Test public void privateAddressesOnly(){for(String ip:new String[]{"192.168.1.44","10.2.3.4","172.16.0.2","172.31.255.2"})PrinterNetworkPolicy.validate(ip,9100);for(String ip:new String[]{"127.0.0.1","8.8.8.8","169.254.1.2","172.32.0.1","192.168.1.999","192.168.01.2","localhost","192.168.1.2/path"}){try{PrinterNetworkPolicy.validate(ip,9100);fail(ip);}catch(IllegalArgumentException expected){}}for(int port:new int[]{0,65536,-1}){try{PrinterNetworkPolicy.validate("10.0.0.1",port);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void completeTicketSentAndConnectionClosed()throws Exception {ByteArrayOutputStream bytes=new ByteArrayOutputStream();boolean[] closed={false};Socket fake=new Socket(){public void connect(SocketAddress address,int timeout){assertEquals(3000,timeout);assertEquals(9100,((InetSocketAddress)address).getPort());}public void setSoTimeout(int t){}public OutputStream getOutputStream(){return bytes;}public synchronized void close(){closed[0]=true;}};byte[] ticket={27,64,29,118,0,9};LanPrinterTransport.send("192.168.1.44",9100,ticket,()->fake);assertArrayEquals(ticket,bytes.toByteArray());assertTrue(closed[0]);}
 @Test public void connectionProbeSendsNoBytes()throws Exception {Socket fake=new Socket(){public void connect(SocketAddress a,int t){}public void setSoTimeout(int t){}public OutputStream getOutputStream(){throw new AssertionError("No se imprime durante una prueba TCP");}};LanPrinterTransport.send("10.0.0.4",9100,new byte[0],()->fake);}
 @Test public void connectionFailureIsNotReportedAsPrinted()throws Exception {try{LanPrinterTransport.send("192.168.1.4",9100,new byte[]{1},()->new Socket(){public void connect(SocketAddress a,int timeout)throws IOException{throw new SocketTimeoutException();}});fail();}catch(IOException error){assertTrue(error.getMessage().contains("SocketTimeoutException"));}}
 @Test public void disconnectDuringWriteIsAnError()throws Exception {try{LanPrinterTransport.send("10.0.0.1",9100,new byte[]{1},()->new Socket(){public void connect(SocketAddress a,int t){}public void setSoTimeout(int t){}public OutputStream getOutputStream(){return new OutputStream(){public void write(int b)throws IOException{throw new IOException("desconexión simulada");}};}});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("IOException"));}}
}
